import React, { useState, useEffect } from "react";
// src/App.jsx

// Change this:
import TaskForm from './components/TaskForm';
// To this:
import AddTaskForm from './components/AddTaskForm';

// Change this:
import TaskFilter from './components/TaskFilter';
// To this:
import FilterControls from './components/FilterControls';

// Change this:
import TaskStats from './components/TaskStats';
// To this:
import Stats from './components/Stats';
import {
  getTasks,
  addTaskAPI,
  updateTaskAPI,
  deleteTaskAPI,
} from "./api/taskService";

const App = () => {
  const [tasks, setTasks] = useState([]);
  const [filter, setFilter] = useState("all");
  const [loading, setLoading] = useState(true);

  // Fetch from API (or fallback to localStorage)
  useEffect(() => {
    const loadTasks = async () => {
      try {
        const apiTasks = await getTasks();
        setTasks(apiTasks);
        localStorage.setItem("tasks", JSON.stringify(apiTasks));
      } catch {
        const saved = localStorage.getItem("tasks");
        if (saved) setTasks(JSON.parse(saved));
      } finally {
        setLoading(false);
      }
    };
    loadTasks();
  }, []);

  useEffect(() => {
    localStorage.setItem("tasks", JSON.stringify(tasks));
  }, [tasks]);

  const addTask = async (title) => {
    if (!title.trim()) return alert("Task name cannot be empty!");
    const newTask = { id: Date.now(), title, completed: false };
    setTasks((prev) => [...prev, newTask]);
    await addTaskAPI(newTask);
  };

  const toggleTask = async (id) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t))
    );
    const task = tasks.find((t) => t.id === id);
    await updateTaskAPI(id, { ...task, completed: !task.completed });
  };

  const deleteTask = async (id) => {
    setTasks((prev) => prev.filter((t) => t.id !== id));
    await deleteTaskAPI(id);
  };

  const editTask = async (id, newTitle) => {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, title: newTitle } : t))
    );
    await updateTaskAPI(id, { title: newTitle });
  };

  const filteredTasks =
    filter === "completed"
      ? tasks.filter((t) => t.completed)
      : filter === "incomplete"
      ? tasks.filter((t) => !t.completed)
      : tasks;

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-3xl mx-auto">
        <h1 className="text-3xl font-bold mb-2 text-gray-800">Task Manager</h1>
        <p className="text-gray-500 mb-6">Organize your tasks efficiently</p>

        {loading ? (
          <div className="text-center text-gray-500">Loading tasks...</div>
        ) : (
          <>
            <TaskStats tasks={tasks} />
            <TaskForm addTask={addTask} />
            <TaskFilter tasks={tasks} filter={filter} setFilter={setFilter} />
            <TaskList
              tasks={filteredTasks}
              toggleTask={toggleTask}
              deleteTask={deleteTask}
              editTask={editTask}
            />
          </>
        )}
      </div>
    </div>
  );
};

export default App;
